}
from collections import Counter
c_total = Counter()
for m in commitments.values():
    c_total.update(m)
remaining = {}
for item, qty in checklist.items():
    remaining[item] = max(0, qty - c_total.get(item,0))
print('committed totals', dict(c_total))
print('remaining', remaining)
remaining_nonzero = {k:v for k,v in remaining.items() if v>0}
print('remaining_nonzero', remaining_nonzero)

